class Solution {
public:
    int findLUSlength(vector<string>& strs) {
        int n = strs.size();
        int ans = -1;
        for (int i = 0; i < n; i++) {
            bool valid = true;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                if (isSubseq(strs[i], strs[j])) {
                    valid = false;
                    break;
                }
            }
            if (valid) ans = max(ans, (int)strs[i].size());
        }
        return ans;
    }
private:
    bool isSubseq(const string& a, const string& b) {
        if (a.size() > b.size()) return false;
        int i = 0;
        for (char c : b) {
            if (i < (int)a.size() && a[i] == c) i++;
        }
        return i == (int)a.size();
    }
};
